  Send, 
  LayoutList, 
  Award,
  Star,
  ChevronRight,
  TrendingUp,
  Sparkles
} from 'lucide-react';
import { DayData, Task, TomorrowPlan } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import confetti from 'canvas-confetti';

interface NightReviewProps {
  dayData: DayData;
  onComplete: (note: string, plan: TomorrowPlan) => void;
  onClose: () => void;
}

const NightReview: React.FC<NightReviewProps> = ({ 
  dayData, 
  onComplete, 
  onClose 
}) => {
  const [note, setNote] = useState('');
  const [plan, setPlan] = useState<TomorrowPlan>({
    englishTopic: '',
    tradingStrategy: '',
    dsaTopic: '',
    flutterReactChapter: ''
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const completedCount = dayData.tasks.filter(t => t.completed).length;
  const totalCount = dayData.tasks.length;
  const percentage = Math.round((completedCount / totalCount) * 100);

  const getPerformanceGrade = (p: number) => {
    if (p >= 95) return { grade: 'A+', color: 'text-emerald-400', glow: 'shadow-emerald-500/50', desc: 'ELITE WARRIOR' };
    if (p >= 85) return { grade: 'A', color: 'text-blue-400', glow: 'shadow-blue-500/50', desc: 'DISCIPLINED' };
    if (p >= 70) return { grade: 'B', color: 'text-indigo-400', glow: 'shadow-indigo-500/50', desc: 'STABLE GROWTH' };
    if (p >= 50) return { grade: 'C', color: 'text-yellow-400', glow: 'shadow-yellow-500/50', desc: 'NEED MOMENTUM' };
    return { grade: 'F', color: 'text-red-500', glow: 'shadow-red-500/50', desc: 'FAILED MISSION' };
  };

  const perf = getPerformanceGrade(percentage);

  const handleLock = () => {
    setIsSubmitting(true);
    if (percentage >= 85) {
      confetti({
        particleCount: 150,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#3b82f6', '#8b5cf6', '#10b981']
      });
    }
    setTimeout(() => {
      onComplete(note, plan);
    }, 1200);
  };

  return (
    <motion.div 
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      className="fixed inset-0 z-[100] flex items-center justify-center p-6 sm:p-10"
    >
      <div className="absolute inset-0 bg-slate-950/90 backdrop-blur-2xl" onClick={onClose} />

      <motion.div 
        initial={{ scale: 0.9, y: 50, rotateX: 10 }}
        animate={{ scale: 1, y: 0, rotateX: 0 }}
        exit={{ scale: 0.95, opacity: 0, y: 20 }}
        className="relative w-full max-w-5xl glass-card border-white/10 overflow-hidden flex flex-col md:flex-row h-full max-h-[90vh] shadow-[0_50px_100px_rgba(0,0,0,0.8)]"
      >
        {/* Left Panel: Stats Recap */}
        <div className="w-full md:w-5/12 bg-[#020617] p-10 border-r border-white/5 space-y-10 overflow-y-auto scrollbar-thin">
          <div className="flex items-center gap-4">
            <div className="w-14 h-14 rounded-3xl bg-blue-600/10 flex items-center justify-center text-blue-400 shadow-2xl border border-white/5">
              <Sparkles size={28} />
            </div>
            <div>
              <h2 className="text-2xl font-black italic tracking-tighter text-white">END OF DAY</h2>
              <p className="text-[10px] text-slate-500 uppercase tracking-[0.3em] font-black">PHASE COMPLETION</p>
            </div>
          </div>

          <div className="space-y-8">
            <div className={`p-8 rounded-[2rem] bg-gradient-to-br from-white/2 to-transparent border border-white/5 text-center relative overflow-hidden group`}>
              <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-blue-500/20 to-transparent" />
              <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Day Performance</p>
              <div className={`text-8xl font-black ${perf.color} drop-shadow-[0_0_20px_rgba(59,130,246,0.2)] mb-2`}>{perf.grade}</div>
              <p className={`text-sm font-black tracking-widest ${perf.color} uppercase`}>{perf.desc}</p>

              <div className="mt-8 space-y-2">
                <div className="flex justify-between text-[10px] font-black text-slate-500 uppercase">
                  <span>Task Velocity</span>
                  <span>{percentage}%</span>
                </div>
                <div className="w-full h-3 bg-white/5 rounded-full overflow-hidden">
                   <motion.div 
                     initial={{ width: 0 }}
                     animate={{ width: `${percentage}%` }}
                     transition={{ duration: 1, ease: "easeOut" }}
                     className={`h-full ${percentage >= 70 ? 'bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.6)]' : 'bg-red-500'}`}
                   />
                </div>
              </div>
            </div>

            <div className="space-y-4">
              <h3 className="text-xs font-black text-slate-500 uppercase tracking-[0.2em] flex items-center gap-3">
                <LayoutList size={16} className="text-blue-500" /> MISSION LOG
              </h3>
              <div className="space-y-3 max-h-52 overflow-y-auto pr-3 scrollbar-thin">
                {dayData.tasks.map(t => (
                  <div key={t.id} className="flex items-center justify-between p-4 rounded-2xl bg-white/2 border border-white/2 hover:border-white/5 transition-all group">
                    <div className="flex items-center gap-3">
                      {t.completed ? <CheckCircle2 size={16} className="text-emerald-500" /> : <XCircle size={16} className="text-red-500" />}
                      <span className={`text-xs font-bold leading-tight ${t.completed ? 'text-slate-300' : 'text-slate-500'}`}>{t.title}</span>
                    </div>
                    {t.completed && <span className="text-[10px] font-black text-emerald-500/50">+{t.points}</span>}
                  </div>
                ))}
              </div>
            </div>
          </div>

          <div className="space-y-4">
             <label className="text-xs font-black text-slate-500 uppercase tracking-[0.2em]">MISSION NOTES</label>
             <textarea 
               value={note}
               onChange={(e) => setNote(e.target.value)}
               placeholder="Reflection on failures or breakthroughs..."
               className="w-full h-36 bg-white/2 border border-white/5 rounded-3xl p-5 text-sm text-slate-200 outline-none focus:border-blue-500/30 transition-all resize-none placeholder:text-slate-700 font-medium"
             />
          </div>
        </div>

        {/* Right Panel: The Plan */}
        <div className="w-full md:w-7/12 p-12 bg-gradient-to-br from-slate-900/50 to-[#020617] flex flex-col overflow-y-auto scrollbar-thin">
          <div className="flex items-center justify-between gap-4 mb-12">
            <div className="flex items-center gap-4">
              <div className="w-14 h-14 rounded-3xl bg-purple-600/10 flex items-center justify-center text-purple-400 border border-white/5">
                <CalendarPlus size={28} />
              </div>
              <div>
                <h2 className="text-2xl font-black italic tracking-tighter text-white uppercase">PRESET TOMORROW</h2>
                <p className="text-[10px] text-slate-500 uppercase tracking-[0.3em] font-black">STRATEGIC PLANNING</p>
              </div>
            </div>
            {percentage === 100 && (
               <div className="flex items-center gap-2 px-4 py-2 bg-yellow-500/10 rounded-full border border-yellow-500/20 animate-pulse">
                  <Star size={14} className="text-yellow-500 fill-yellow-500" />
                  <span className="text-[10px] font-black text-yellow-500 uppercase tracking-widest">PERFECT SCORE</span>
               </div>
            )}
          </div>

          <div className="flex-1 space-y-8">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-8">
              <PlanInput 
                label="English Mastery" 
                value={plan.englishTopic} 
                onChange={(val) => setPlan({...plan, englishTopic: val})} 
                placeholder="Topic or Article" 
              />
              <PlanInput 
                label="Trade Strategy" 
                value={plan.tradingStrategy} 
                onChange={(val) => setPlan({...plan, tradingStrategy: val})} 
                placeholder="Focus logic" 
              />
              <PlanInput 
                label="DSA/Logic" 
                value={plan.dsaTopic} 
                onChange={(val) => setPlan({...plan, dsaTopic: val})} 
                placeholder="Topic / Pattern" 
              />
              <PlanInput 
                label="Dev Feature" 
                value={plan.flutterReactChapter} 
                onChange={(val) => setPlan({...plan, flutterReactChapter: val})} 
                placeholder="Modular Target" 
              />
            </div>

            <div className="p-8 rounded-[2.5rem] bg-indigo-600/5 border border-indigo-500/10 mt-10 relative overflow-hidden group">
              <div className="absolute -right-10 -bottom-10 w-40 h-40 bg-indigo-500/5 blur-3xl group-hover:bg-indigo-500/10 transition-all" />
              <div className="flex gap-6 relative z-10">
                <Award className="text-indigo-400 mt-1" size={32} />
                <div className="space-y-2">
                  <h4 className="text-lg font-black text-white italic uppercase tracking-tight">The Momentum Law</h4>
                  <p className="text-xs text-slate-400 leading-relaxed font-medium">
                    Static planning tonight eliminates morning resistance. By locking tomorrow's 
                    targets now, you've already won 50% of the battle.
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="mt-12 flex gap-6">
             <button 
               onClick={onClose}
               className="flex-1 py-5 rounded-[2.5rem] border border-white/5 font-black text-xs tracking-widest text-slate-500 hover:bg-white/5 transition-all uppercase"
             >
               ABORT
             </button>
             <button 
               onClick={handleLock}
               disabled={isSubmitting}
               className="flex-[2] py-5 rounded-[2.5rem] bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 hover:shadow-[0_0_40px_rgba(59,130,246,0.3)] hover:scale-[1.01] active:scale-[0.98] font-black text-xs text-white uppercase tracking-[0.2em] shadow-2xl transition-all flex items-center justify-center gap-4 relative overflow-hidden"
             >
               {isSubmitting ? (
                 <div className="flex items-center gap-2">
                    <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                    <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                    <div className="w-1.5 h-1.5 bg-white rounded-full animate-bounce"></div>
                 </div>
               ) : (
                 <>
                   <Send size={18} /> INITIALIZE TOMORROW
                 </>
               )}
             </button>
          </div>
        </div>
      </motion.div>
    </motion.div>
  );
};

const PlanInput = ({ label, value, onChange, placeholder }: { label: string, value: string, onChange: (v: string) => void, placeholder: string }) => (
  <div className="space-y-3">
    <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em] ml-2">{label}</label>
    <div className="relative group">
      <input 
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="w-full bg-white/2 border border-white/5 rounded-3xl p-5 text-sm text-slate-100 outline-none focus:border-blue-500/50 group-hover:border-white/10 transition-all font-bold placeholder:text-slate-800 placeholder:font-black placeholder:uppercase placeholder:text-[10px]"
      />
      <div className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-800 group-hover:text-blue-500/30 transition-colors">
        <ChevronRight size={18} />
      </div>
    </div>
  </div>
);

export default NightReview;
